      "desc": "Vampire Lord Valthar has ruled Mirkwood forest for five centuries. He has turned half of its inhabitants into blood-sucking undead.",
      "flavor": "«He drinks from our fear before he drinks our blood.» — Mirkwood Survivor",
      "difficulty": "Difficile",
